import { DESIGN_CSS, PRIMITIVES_CSS } from './design/generated.ts';
/**
 * The public pages: the landing page at /, /privacy, /terms, /support and /security, the screenshots
 * they show (/site/chat-*.png, from scripts/screenshots.ts), the launch video (/site/launch.mp4, made with /brag from those
 * scenes), and the brand files browsers and link previews ask for
 * (favicon, app icon, social card; generated by scripts/brand.ts). No scripts, no
 * third-party requests.
 *
 * The privacy policy describes what this software stores and sends. It applies to
 * whoever runs the server; MCPORTAL_OPERATOR names them on the pages.
 */
